<header class="admin-top"><div><p>Audience</p><h1>Notifications</h1></div></header><section class="admin-panel"><table class="admin-table"><thead><tr><th>Notification</th><th>User</th><th>Story</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($notifications as $n):?><tr><td><strong><?=pm_e($n['title']??'')?></strong><small><?=pm_e($n['body']??'')?></small></td><td><?=pm_e($n['user_id']??'')?></td><td><?=pm_e($n['story_id']??'')?></td><td><?=empty($n['read_at'])?'Unread':'Read'?></td><td><?=pm_e($n['created_at']??'')?></td></tr><?php endforeach;?></tbody></table><?php if(!$notifications):?><div class="admin-empty">No notifications generated yet. Follow a live story in the public app, then add a live update.</div><?php endif;?></section>
